'use client'

import * as React from 'react'

import './preferences.css'
import './gamestage-primitives.css'
import { Row } from './row'
import { Toggle } from './toggle'
import { ChevronGlyph } from './glyphs'

/**
 * Preferences: a fan's settings for a game, as one group on their Profile.
 *
 * Tom, 2026-09-28: "this toggle is out of place, we should have a sub-area for
 * Preferences". The sound toggle floated alone on the Profile page with
 * Privacy settings and a copyright link loose underneath it. This is the
 * settings-app shape instead: a heading, then one grouped list of full-width
 * rows, a toggle at the end of a row that switches and a chevron at the end of
 * a row that opens something, and the copyright link as a small line below the
 * group rather than a row of its own.
 *
 * It owns no words: every label arrives from the host, which reads them from
 * Studio. It performs nothing: a toggle reports its new value and a row
 * reports the press.
 *
 * A `slot` row is a row the host or the Gamestage client fills. The client
 * looks for `data-gs-slot="privacy-settings"` and puts its Privacy settings
 * control there, so the control lands inside the group, drawn as a row.
 */

export type PreferencesItem =
  | { kind: 'toggle'; id: string; label: string; checked: boolean; onChange: (checked: boolean) => void; disabled?: boolean }
  | { kind: 'link'; id: string; label: string; onOpen: () => void; value?: React.ReactNode }
  | { kind: 'slot'; id: string; slot: string }

export interface PreferencesProps extends Omit<React.HTMLAttributes<HTMLElement>, 'title'> {
  /** The heading, e.g. "Preferences". */
  title: string
  /** The rows, in order. */
  items: PreferencesItem[]
  /** A small link under the group, e.g. "Report copyright infringement". */
  footer?: { label: string; onOpen: () => void }
}

export function Preferences(props: PreferencesProps) {
  const { title, items, footer, className, ...rest } = props
  const headingId = React.useId()

  return (
    <section
      {...rest}
      className={['gs-preferences', className].filter(Boolean).join(' ')}
      data-gs-component="preferences"
      aria-labelledby={headingId}
    >
      <h2 id={headingId} className="gs-preferences__title" data-gs-scope="preferences" data-gs-part="label">
        {title}
      </h2>
      <ul className="gs-preferences__group" data-gs-scope="preferences" data-gs-part="list">
        {items.map((item) => (
          <li key={item.id} className="gs-preferences__item" data-gs-scope="preferences" data-gs-part="row">
            {item.kind === 'toggle' ? (
              <Row
                label={item.label}
                actions={
                  <Toggle label={item.label} labelHidden checked={item.checked} disabled={item.disabled} onChange={item.onChange} />
                }
              />
            ) : item.kind === 'link' ? (
              <Row
                label={item.label}
                value={item.value}
                onSelect={item.onOpen}
                actions={
                  <span className="gs-preferences__chevron" aria-hidden="true">
                    <ChevronGlyph direction="right" />
                  </span>
                }
              />
            ) : (
              <div className="gs-preferences__slot" data-gs-slot={item.slot} />
            )}
          </li>
        ))}
      </ul>
      {footer ? (
        <button
          type="button"
          className="gs-preferences__footer gs-action-type gs-pressable"
          data-gs-scope="preferences"
          data-gs-part="trigger"
          onClick={footer.onOpen}
        >
          {footer.label}
        </button>
      ) : null}
    </section>
  )
}

/* Preferences. Every value comes from a token; nothing here is a literal
   colour. One grouped list: the rows share one surface and one edge, joined
   by a hairline, as a settings app draws them. */

.gs-preferences {
  display: grid;
  gap: var(--gs-space-2);
  min-inline-size: 0;
}

.gs-preferences__title {
  margin: 0;
  padding-inline: var(--gs-space-1);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-ink-secondary);
}

/* One column that may be narrower than its longest row: without the
   minmax a row's min-content sets the column, and at 320px on a wider
   fallback face the rows ran 3px past the group's edge. */
.gs-preferences__group {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  margin: 0;
  padding: 0;
  list-style: none;
  overflow: hidden;
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-surface);
}

.gs-preferences__item {
  min-inline-size: 0;
}

.gs-preferences__item + .gs-preferences__item {
  border-block-start: var(--gs-stroke-hairline) solid var(--gs-color-edge);
}

/* Inside the group a row is a line of the group, not a card of its own. */
.gs-preferences__item > .gs-row {
  inline-size: 100%;
  min-block-size: var(--gs-size-touch-min);
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.gs-preferences__chevron {
  display: inline-flex;
  color: var(--gs-color-ink-secondary);
  font-size: var(--gs-size-icon-utility);
}

/* The client's Privacy settings control lands here: drawn as the row it sits
   in, the whole width, with a chevron at its end. */
.gs-preferences__slot:empty {
  display: none;
}

/* Two classes, not one: the client injects its own one-class rules for these
   links after this stylesheet (display: inline, a margin, its own padding),
   and at equal weight the later rule won, so Privacy settings drew as inline
   underlined text with the chevron collapsed to a bar beside it. */
.gs-preferences .gs-preferences__slot > * {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  inline-size: 100%;
  min-block-size: var(--gs-size-touch-min);
  margin: 0;
  padding: 0 var(--gs-space-3);
  font: inherit;
  /* The row label's type, so the client's control reads as one of the rows. */
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-ink);
  text-align: start;
  text-decoration: none;
  background: transparent;
  border: 0;
  border-radius: 0;
  cursor: pointer;
}

.gs-preferences .gs-preferences__slot > *::after {
  content: '';
  inline-size: 0.5em;
  block-size: 0.5em;
  border: solid var(--gs-color-ink-secondary);
  border-width: var(--gs-stroke-ui) var(--gs-stroke-ui) 0 0;
  rotate: 45deg;
  flex: none;
}

/* The client puts its copyright link in the same slot, after Privacy
   settings. It is a caption under the group, not a row: small, secondary,
   underlined, with no chevron. Tom, 2026-09-28. */
.gs-preferences .gs-preferences__slot > [data-gs-part='copyright'] {
  justify-content: flex-start;
  min-block-size: var(--gs-size-touch-min);
  margin-block-start: var(--gs-space-2);
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  color: var(--gs-color-ink-secondary);
  text-decoration: underline;
  text-underline-offset: 3px;
  border-block-start: var(--gs-stroke-hairline) solid var(--gs-color-edge);
}

.gs-preferences .gs-preferences__slot > [data-gs-part='copyright']::after {
  content: none;
}

.gs-preferences__footer {
  justify-self: start;
  min-block-size: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-1);
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  color: var(--gs-color-ink-secondary);
  text-decoration: underline;
  text-underline-offset: 3px;
  background: none;
  border: 0;
  cursor: pointer;
}

.gs-preferences .gs-preferences__slot > *:focus-visible,
.gs-preferences__footer:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-selected);
  outline-offset: -4px;
}
